import { router } from 'expo-router';

import { Btn, Card, Screen, StepDot, Sub, T, TaskRow } from '@/components/ui';
import { PLAN_STEPS } from '@/data/demo';
import { usePatient, useStore } from '@/state/store';

/** Shows the plan exactly as confirmed from the discharge summary. Nothing here is generated by the app. */
export default function CarePlan() {
  const patient = usePatient();
  const live = useStore((s) => s.live);
  const plan = useStore((s) => s.plan);
  const hasSummary = useStore((s) => s.hasSummary);
  const isSample = useStore((s) => s.isSample);
  const fu = patient.followUp;
  const section = (title: string, items: string[], tone?: 'red') => items.length ? (
    <>
      <T v="sect">{title}</T>
      <Card tone={tone}>{items.map((x, i) => <TaskRow key={x + i} title={x} last={i === items.length - 1} />)}</Card>
    </>
  ) : null;

  return (
    <Screen>
      <T v="label">Care plan</T>
      <T v="h2">Your recovery plan</T>
      <Sub>
        {hasSummary
          ? `From your discharge summary${patient.doctor ? ` by ${patient.doctor}` : ''}${patient.hospital ? `, ${patient.hospital}` : ''}, checked by you. Home Konnect does not change it.`
          : live ? 'Add your discharge summary and your plan appears here.' : 'Sample plan. Add your discharge summary and this fills in from your own document.'}
      </Sub>
      {!live && isSample ? (
        <>
          <T v="sect" style={{ marginTop: 0 }}>First two weeks (sample)</T>
          <Card>
            {PLAN_STEPS.map((p, i) => <TaskRow key={p.t} left={<StepDot n={i + 1} />} title={p.t} sub={p.s} last={i === PLAN_STEPS.length - 1} />)}
          </Card>
        </>
      ) : null}
      {fu ? section('Follow-up', [`${fu.dept} · ${fu.when}${fu.where ? ` · ${fu.where}` : ''}`]) : null}
      {section("Doctor's limits", [`Keep blood pressure below ${patient.bpLimit.sys}/${patient.bpLimit.dia}`, ...plan.limits])}
      {section('Diet and activity', plan.dietActivity)}
      {section('Allergies', plan.allergies)}
      {section('Call for help straight away if', plan.warningSigns, 'red')}
      {hasSummary && !plan.warningSigns.length ? (
        <Card tone="amber"><T v="small">Your summary did not list warning signs. Ask your doctor which symptoms need urgent care.</T></Card>
      ) : null}
      {!hasSummary && live ? <Btn title="Add discharge summary" onPress={() => router.push('/onboarding/upload')} style={{ marginBottom: 10 }} /> : null}
      <Btn v="red" title="Open SOS" onPress={() => router.push('/sos')} style={{ marginTop: 6 }} />
    </Screen>
  );
}
